  var Hp = opt.Hp || 360, skala = Hp / 360;
  var Hv = Math.round(84 * skala), Hs = Math.round(96 * skala), GAP = Math.round(26 * skala);

  var N = bars.length;
  var T = [], O = [], H = [], L = [], C = [], V = [];
  for (var i = 0; i < N; i++) { T.push(bars[i][0]); O.push(bars[i][1]); H.push(bars[i][2]); L.push(bars[i][3]); C.push(bars[i][4]); V.push(bars[i][5]); }

